        RECT r;GetClientRect(h,&r);int margin=px(16),width=r.right-2*margin;
        auto move=[&](int id,int x,int y,int w,int height){if(auto child=GetDlgItem(h,id))SetWindowPos(child,0,x,y,w,height,SWP_NOZORDER|SWP_NOACTIVATE);};
        move(610,margin,px(16),width,px(26));move(611,margin,px(48),width,px(34));
