        if(m==WM_DPICHANGED&&d){auto bounds=(RECT*)l;SetWindowPos(h,0,bounds->left,bounds->top,bounds->right-bounds->left,bounds->bottom-bounds->top,SWP_NOZORDER|SWP_NOACTIVATE);d->layout(h,HIWORD(w));return TRUE;}
